insert into public.translations (locale, key, value) values
  ('pt-BR', 'guidance.agentNoModel', $json$"nenhum modelo dos agentes ligados ({agents}) está ligado"$json$::jsonb),
  ('en', 'guidance.agentNoModel', $json$"none of the models of the agents that are on ({agents}) is turned on"$json$::jsonb),
  ('es', 'guidance.agentNoModel', $json$"ningún modelo de los agentes activados ({agents}) está activado"$json$::jsonb),
  ('zh-CN', 'guidance.agentNoModel', $json$"已开启的智能体（{agents}）没有开启任何模型"$json$::jsonb),
  ('hi', 'guidance.agentNoModel', $json$"चालू एजेंटों ({agents}) का कोई भी मॉडल चालू नहीं है"$json$::jsonb),
  ('ar', 'guidance.agentNoModel', $json$"لا يوجد أي نموذج مفعّل للوكلاء المفعّلين ({agents})"$json$::jsonb),
  ('fr', 'guidance.agentNoModel', $json$"aucun modèle des agents activés ({agents}) n'est activé"$json$::jsonb),
  ('ru', 'guidance.agentNoModel', $json$"ни одна модель включённых агентов ({agents}) не включена"$json$::jsonb),
  ('ja', 'guidance.agentNoModel', $json$"オンのエージェント（{agents}）のモデルがどれもオンになっていません"$json$::jsonb),
  ('de', 'guidance.agentNoModel', $json$"kein Modell der eingeschalteten Agenten ({agents}) ist eingeschaltet"$json$::jsonb),
  ('pt-BR', 'guidance.agentNoModelFix', $json$"Abra Configurações, abra a aba de um desses agentes e ligue pelo menos um modelo na lista Modelos (os modelos começam desligados)."$json$::jsonb),
  ('en', 'guidance.agentNoModelFix', $json$"Open Settings, open the tab of one of those agents and turn on at least one model in its Models list (models start off)."$json$::jsonb),
  ('es', 'guidance.agentNoModelFix', $json$"Abre Configuración, abre la pestaña de uno de esos agentes y activa al menos un modelo en su lista Modelos (los modelos empiezan desactivados)."$json$::jsonb),
  ('zh-CN', 'guidance.agentNoModelFix', $json$"打开设置，进入其中一个智能体的标签页，在“模型”列表中至少开启一个模型（模型默认关闭）。"$json$::jsonb),
  ('hi', 'guidance.agentNoModelFix', $json$"सेटिंग्स खोलें, इनमें से किसी एजेंट का टैब खोलें और उसकी मॉडल सूची में कम से कम एक मॉडल चालू करें (मॉडल बंद से शुरू होते हैं)।"$json$::jsonb),
  ('ar', 'guidance.agentNoModelFix', $json$"افتح الإعدادات، ثم تبويب أحد هؤلاء الوكلاء، وشغّل نموذجًا واحدًا على الأقل في قائمة النماذج (تبدأ النماذج معطّلة)."$json$::jsonb),
  ('fr', 'guidance.agentNoModelFix', $json$"Ouvrez les Réglages, l'onglet de l'un de ces agents et activez au moins un modèle dans sa liste Modèles (les modèles démarrent désactivés)."$json$::jsonb),
  ('ru', 'guidance.agentNoModelFix', $json$"Откройте Настройки, вкладку одного из этих агентов и включите хотя бы одну модель в списке «Модели» (модели по умолчанию выключены)."$json$::jsonb),
  ('ja', 'guidance.agentNoModelFix', $json$"設定を開き、これらのエージェントのいずれかのタブで、モデル一覧のモデルを少なくとも 1 つオンにしてください（モデルは初期状態でオフです）。"$json$::jsonb),
  ('de', 'guidance.agentNoModelFix', $json$"Öffne die Einstellungen, den Tab eines dieser Agenten, und schalte in seiner Modellliste mindestens ein Modell ein (Modelle starten ausgeschaltet)."$json$::jsonb),
  ('pt-BR', 'model.noneOn', $json$"Este agente está ligado, mas nenhum modelo dele está. Ligue pelo menos um para o Jev poder usar o agente."$json$::jsonb),
  ('en', 'model.noneOn', $json$"This agent is on, but none of its models is. Turn on at least one so Jev can use the agent."$json$::jsonb),
  ('es', 'model.noneOn', $json$"Este agente está activado, pero ninguno de sus modelos lo está. Activa al menos uno para que Jev pueda usar el agente."$json$::jsonb),
  ('zh-CN', 'model.noneOn', $json$"此智能体已开启，但它的模型都未开启。请至少开启一个，Jev 才能使用该智能体。"$json$::jsonb),
  ('hi', 'model.noneOn', $json$"यह एजेंट चालू है, लेकिन इसका कोई मॉडल चालू नहीं है। कम से कम एक चालू करें ताकि Jev एजेंट का उपयोग कर सके।"$json$::jsonb),
  ('ar', 'model.noneOn', $json$"هذا الوكيل مفعّل، لكن لا يوجد أي نموذج مفعّل له. فعّل نموذجًا واحدًا على الأقل ليتمكن Jev من استخدام الوكيل."$json$::jsonb),
  ('fr', 'model.noneOn', $json$"Cet agent est activé, mais aucun de ses modèles ne l'est. Activez-en au moins un pour que Jev puisse utiliser l'agent."$json$::jsonb),
  ('ru', 'model.noneOn', $json$"Этот агент включён, но ни одна его модель не включена. Включите хотя бы одну, чтобы Jev мог использовать агента."$json$::jsonb),
  ('ja', 'model.noneOn', $json$"このエージェントはオンですが、モデルがどれもオンではありません。Jev が使えるよう、少なくとも 1 つオンにしてください。"$json$::jsonb),
  ('de', 'model.noneOn', $json$"Dieser Agent ist eingeschaltet, aber keines seiner Modelle. Schalte mindestens eines ein, damit Jev den Agenten nutzen kann."$json$::jsonb),
  ('pt-BR', 'model.refresh.hint', $json$"Lê a lista do comando /model do agente. O que você mudou na lista fica, os modelos novos começam desligados e os que o agente deixou de oferecer saem."$json$::jsonb),
  ('en', 'model.refresh.hint', $json$"Reads the list from the agent's /model command. What you changed in the list is kept, new models start off and the ones the agent no longer offers leave."$json$::jsonb),
  ('es', 'model.refresh.hint', $json$"Lee la lista del comando /model del agente. Lo que cambiaste en la lista se conserva, los modelos nuevos empiezan desactivados y los que el agente ya no ofrece salen."$json$::jsonb),
  ('zh-CN', 'model.refresh.hint', $json$"从智能体的 /model 命令读取列表。你对列表所做的修改会保留，新模型默认关闭，智能体不再提供的模型会被移除。"$json$::jsonb),
  ('hi', 'model.refresh.hint', $json$"एजेंट के /model कमांड से सूची पढ़ता है। सूची में आपके बदलाव बने रहते हैं, नए मॉडल बंद से शुरू होते हैं और जिन्हें एजेंट अब नहीं देता वे हट जाते हैं।"$json$::jsonb),
  ('ar', 'model.refresh.hint', $json$"يقرأ القائمة من أمر /model الخاص بالوكيل. ما غيّرته في القائمة يبقى، والنماذج الجديدة تبدأ معطّلة، وما لم يعد الوكيل يقدمه يُزال."$json$::jsonb),
  ('fr', 'model.refresh.hint', $json$"Lit la liste depuis la commande /model de l'agent. Vos modifications de la liste sont conservées, les nouveaux modèles démarrent désactivés et ceux que l'agent n'offre plus disparaissent."$json$::jsonb),
  ('ru', 'model.refresh.hint', $json$"Читает список из команды /model агента. Ваши изменения в списке сохраняются, новые модели выключены, а те, что агент больше не предлагает, удаляются."$json$::jsonb),
  ('ja', 'model.refresh.hint', $json$"エージェントの /model コマンドから一覧を読み込みます。一覧で変更した内容は保持され、新しいモデルはオフで始まり、エージェントが提供しなくなったものは削除されます。"$json$::jsonb),
  ('de', 'model.refresh.hint', $json$"Liest die Liste aus dem /model-Befehl des Agenten. Deine Änderungen an der Liste bleiben, neue Modelle starten ausgeschaltet und die, die der Agent nicht mehr anbietet, entfallen."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modelsOffHint.title', $json$"Ligar um agente sem nenhum modelo agora avisa"$json$::jsonb),
  ('en', 'whatsNew.item.modelsOffHint.title', $json$"Turning on an agent without any model now says so"$json$::jsonb),
  ('es', 'whatsNew.item.modelsOffHint.title', $json$"Activar un agente sin ningún modelo ahora lo avisa"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modelsOffHint.title', $json$"开启没有任何模型的智能体时现在会提示"$json$::jsonb),
  ('hi', 'whatsNew.item.modelsOffHint.title', $json$"बिना किसी मॉडल के एजेंट चालू करने पर अब चेतावनी मिलती है"$json$::jsonb),
  ('ar', 'whatsNew.item.modelsOffHint.title', $json$"تشغيل وكيل بلا أي نموذج صار ينبّه إلى ذلك"$json$::jsonb),
  ('fr', 'whatsNew.item.modelsOffHint.title', $json$"Activer un agent sans aucun modèle le signale désormais"$json$::jsonb),
  ('ru', 'whatsNew.item.modelsOffHint.title', $json$"Включение агента без моделей теперь сопровождается предупреждением"$json$::jsonb),
  ('ja', 'whatsNew.item.modelsOffHint.title', $json$"モデルが1つもないエージェントをオンにすると通知されるようになりました"$json$::jsonb),
  ('de', 'whatsNew.item.modelsOffHint.title', $json$"Einen Agenten ohne Modell einzuschalten, wird jetzt gemeldet"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modelsOffHint.detail', $json$"Um agente ligado com todos os modelos desligados mostra um aviso na lista Modelos, e o erro do pedido nomeia esses agentes e manda ligar um modelo. O Carregar do CLI também funciona com alterações não salvas: ele junta a lista ao rascunho em vez de ficar desabilitado."$json$::jsonb),
  ('en', 'whatsNew.item.modelsOffHint.detail', $json$"An agent that is on with every model off shows a notice in its Models list, and the request failure names those agents and says to turn on a model. Load from the CLI also works with unsaved changes now: it merges the list into your draft instead of staying disabled."$json$::jsonb),
  ('es', 'whatsNew.item.modelsOffHint.detail', $json$"Un agente activado con todos los modelos desactivados muestra un aviso en su lista Modelos, y el error de la solicitud nombra esos agentes y pide activar un modelo. Cargar desde la CLI también funciona con cambios sin guardar: une la lista a tu borrador en lugar de quedar deshabilitado."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modelsOffHint.detail', $json$"已开启但所有模型都关闭的智能体会在其“模型”列表中显示提示，请求失败时也会点名这些智能体并提示开启模型。“从 CLI 加载”现在在有未保存更改时也能使用：它会把列表合并进你的草稿，而不是保持禁用。"$json$::jsonb),
  ('hi', 'whatsNew.item.modelsOffHint.detail', $json$"जो एजेंट चालू है पर उसके सभी मॉडल बंद हैं, उसकी मॉडल सूची में चेतावनी दिखती है, और अनुरोध की विफलता में उन एजेंटों का नाम आता है और मॉडल चालू करने को कहा जाता है। “CLI से लोड करें” अब बिना सहेजे बदलावों के साथ भी काम करता है: यह सूची को आपके ड्राफ्ट में मिला देता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.modelsOffHint.detail', $json$"يعرض الوكيل المفعّل الذي جميع نماذجه معطّلة تنبيهًا في قائمة النماذج، ويسمّي خطأ الطلب هؤلاء الوكلاء ويطلب تشغيل نموذج. كما يعمل «تحميل من CLI» الآن مع التغييرات غير المحفوظة: يدمج القائمة في مسودتك بدل أن يبقى معطّلًا."$json$::jsonb),
  ('fr', 'whatsNew.item.modelsOffHint.detail', $json$"Un agent activé dont tous les modèles sont désactivés affiche un avis dans sa liste Modèles, et l'échec de la demande nomme ces agents et demande d'activer un modèle. Charger depuis la CLI fonctionne aussi avec des modifications non enregistrées : il fusionne la liste dans votre brouillon au lieu de rester désactivé."$json$::jsonb),
  ('ru', 'whatsNew.item.modelsOffHint.detail', $json$"Включённый агент со всеми выключенными моделями показывает уведомление в списке «Модели», а ошибка запроса называет этих агентов и просит включить модель. «Загрузить из CLI» теперь работает и с несохранёнными изменениями: список вливается в ваш черновик, а не остаётся недоступным."$json$::jsonb),
  ('ja', 'whatsNew.item.modelsOffHint.detail', $json$"オンだがすべてのモデルがオフのエージェントは、モデル一覧に通知を表示し、リクエストの失敗時にもそのエージェント名を挙げてモデルをオンにするよう案内します。「CLI から読み込む」は未保存の変更があっても使え、無効のままにならず一覧を下書きに統合します。"$json$::jsonb),
  ('de', 'whatsNew.item.modelsOffHint.detail', $json$"Ein eingeschalteter Agent, dessen Modelle alle aus sind, zeigt in seiner Modellliste einen Hinweis, und der Fehler der Anfrage nennt diese Agenten und fordert zum Einschalten eines Modells auf. Aus der CLI laden funktioniert jetzt auch mit ungespeicherten Änderungen: Es führt die Liste in deinen Entwurf zusammen, statt deaktiviert zu bleiben."$json$::jsonb)
